// 기존 Extension 정보 및 Config 준비
const input = $input.first().json["data"];
const { data: arrInput } = JSON.parse(input);
const tokenData = $('Merge Token & Credentials').first().json;


// 기존 설치된 extension 목록 파싱
// const arrInput = Array.isArray(input) ? input : [input];

const existingExtensions = (arrInput || []).map(ext => ({
  id: ext.id,
  name: ext.attributes?.name,
  delegateDescriptorId: ext.attributes?.delegate_descriptor_id,
  extensionPackage: ext.relationships.extension_package.data.id
}));

// Core Extension ID 찾기
const coreExt = existingExtensions.find(ext => 
  ext.delegateDescriptorId?.includes('core::') || ext.name?.toLowerCase() === 'core'
);

// Alloy/Web SDK Extension ID 찾기
const alloyExt = existingExtensions.find(ext => 
  ext.delegateDescriptorId?.includes('alloy') || 
  ext.delegateDescriptorId?.includes('adobe-cloud-connector') ||
  ext.name?.toLowerCase().includes('web sdk') ||
  ext.name?.toLowerCase().includes('alloy')
);

// delegation ID 추출 - rule component 생성시 사용
return [{
  json: {    
    accessToken: tokenData.access_token,
    credentials: tokenData.credentials,
    existingExtensions,
    coreExtensionId: coreExt?.id,
    alloyExtensionId: alloyExt?.id,
    alloyInstalled: !!alloyExt
  }
}];

