    ruleName: rule.name,
    ruleEvents: rule.events,
    ruleConditions: rule.conditions || [],
    ruleActions: rule.actions,
    totalRules: launchConfig.rules.length
  }
}));

// Rule 생성 결과에서 ID 추출하고 Components 준비
const ruleResult = $input.first().json;
const prevData = $('Loop Rules').first().json;

const ruleObj = JSON.parse(ruleResult.data);
const ruleId = ruleObj?.data.id;

const descriptorMapping = {
  "adobe-alloy/src/lib/actions/sendEvent.js": "adobe-alloy::actions::send-event",
"core/src/lib/events/click.js": "core::events::click"
}


if (!ruleId) {
  throw new Error(`Rule 생성 실패 (${prevData.ruleName}): ${JSON.stringify(ruleResult)}`);
}

// Rule Components (Events, Conditions, Actions) 준비
const components = [];

// Events
prevData.ruleEvents?.forEach((evt, idx) => {
  components.push({
    componentType: 'events',
    order: idx,
    modulePath: evt.modulePath,
    extensionDescriptorId: descriptorMapping[evt.modulePath],
    extensionId: prevData.coreExtensionId, // Events는 항상 Core
    settings: JSON.stringify(evt.settings || {}),
    name: `Event ${idx + 1}`
  });
});

// Conditions
prevData.ruleConditions?.forEach((cond, idx) => {
  components.push({
    componentType: 'conditions',
    order: idx,
    modulePath: cond.modulePath,
    extensionId: prevData.coreExtensionId, // Conditions도 보통 Core
    settings: JSON.stringify(cond.settings || {}),
    name: `Condition ${idx + 1}`,
    negate: false
  });
});

// Actions
prevData.ruleActions?.forEach((act, idx) => {
  const isAlloy = act.modulePath?.includes('alloy');
  components.push({
    componentType: 'actions',
    order: idx,
    modulePath: act.modulePath,
    extensionDescriptorId: descriptorMapping[act.modulePath],
    extensionId: isAlloy ? prevData.alloyExtensionId : prevData.coreExtensionId,
    settings: JSON.stringify(act.settings || {}),
    name: `Action ${idx + 1}`
  });
});

// 각 Component를 개별 아이템으로 출력
return components.map(comp => ({
  json: {
    ...prevData,
    ruleId,
    component: comp
  }
}));

